import React, { useState, useRef, useEffect } from "react";
import { useReactToPrint } from "react-to-print";

export default function ParkingApp() {
  const [carNumber, setCarNumber] = useState("");
  const [carType, setCarType] = useState("");
  const [entryTime, setEntryTime] = useState("");
  const [parkingRecords, setParkingRecords] = useState(() => {
    const stored = localStorage.getItem("parkingRecords");
    return stored ? JSON.parse(stored) : [];
  });
  const [activeReceipt, setActiveReceipt] = useState(null);
  const [editingId, setEditingId] = useState(null);

  useEffect(() => {
    localStorage.setItem("parkingRecords", JSON.stringify(parkingRecords));
  }, [parkingRecords]);

  const printRef = useRef();
  const handlePrint = useReactToPrint({
    content: () => printRef.current,
    documentTitle: "주차_영수증",
  });

  const isValidTime = (time) => /^\d{1,2}:\d{2}$/.test(time);

  const getCurrentTime = () => {
    const now = new Date();
    return now.toTimeString().slice(0, 5);
  };

  const handleSetEntryTime = () => {
    setEntryTime(getCurrentTime());
  };

  const handleAddEntry = () => {
    if (!carNumber || !entryTime) {
      alert("차량번호와 입차시간을 입력해주세요.");
      return;
    }
    if (!isValidTime(entryTime)) {
      alert("입차 시간 형식이 잘못되었습니다. (예: 7:30 또는 07:30)");
      return;
    }
    if (parkingRecords.some((r) => r.carNumber === carNumber && !r.exitTime)) {
      alert("이미 입차 등록된 차량입니다.");
      return;
    }

    setParkingRecords([
      ...parkingRecords,
      {
        id: Date.now(),
        carNumber,
        carType,
        entryTime,
        exitTime: "",
        fee: null,
        totalMinutes: null,
      },
    ]);
    setCarNumber("");
    setCarType("");
    setEntryTime("");
  };

  const handleSetExitAndCalculate = (recordId) => {
    const nowTime = getCurrentTime();
    const updatedRecords = parkingRecords.map((r) => {
      if (r.id === recordId) {
        const exitTime = nowTime;
        const [eh, em] = r.entryTime.split(":" ).map(Number);
        const [xh, xm] = exitTime.split(":" ).map(Number);
        const entry = new Date();
        entry.setHours(eh, em, 0, 0);
        const exit = new Date();
        exit.setHours(xh, xm, 0, 0);
        if (exit <= entry) exit.setDate(exit.getDate() + 1);

        const totalMinutes = Math.floor((exit - entry) / 60000);
        const totalHours = Math.ceil(totalMinutes / 60);
        const baseFee = 2000;
        const hourlyFee = 1000;
        const fee = totalHours <= 1 ? baseFee : baseFee + (totalHours - 1) * hourlyFee;

        const updated = { ...r, exitTime, fee, totalMinutes };
        setActiveReceipt(updated);
        return updated;
      }
      return r;
    });

    setParkingRecords(updatedRecords);
  };

  const handleEditChange = (id, field, value) => {
    if (field === "entryTime" || field === "exitTime") {
      value = value.replace(/[^0-9]/g, "");
      if (value.length === 3) value = value[0] + ":" + value.slice(1);
      else if (value.length === 4) value = value.slice(0, 2) + ":" + value.slice(2);
    }
    setParkingRecords(
      parkingRecords.map((r) =>
        r.id === id ? { ...r, [field]: value } : r
      )
    );
  };

  const handleEditDone = (id) => {
    const record = parkingRecords.find((r) => r.id === id);
    if (!isValidTime(record.entryTime)) {
      alert("입차 시간 형식이 잘못되었습니다. (예: 07:30)");
      return;
    }
    if (record.exitTime && !isValidTime(record.exitTime)) {
      alert("출차 시간 형식이 잘못되었습니다. (예: 07:30)");
      return;
    }
    setEditingId(null);
  };

  const generateReceiptText = (record) => {
    if (!record.fee || !record.totalMinutes || !record.exitTime) {
      return "⚠️ 정산이 완료되지 않았습니다. 먼저 정산을 완료해주세요.";
    }

    const baseFee = 2000;
    const hourlyFee = 1000;
    const formatDuration = (minutes) => {
      const h = Math.floor(minutes / 60);
      const m = minutes % 60;
      return `${h}시간 ${m}분`;
    };

    return `====== 🧾 주차 요금 영수증 ======
차량 번호     : ${record.carNumber}
차량 종류     : ${record.carType || "-"}
입차 시간     : ${record.entryTime}
출차 시간     : ${record.exitTime}
주차 시간     : ${record.totalMinutes}분 (${formatDuration(record.totalMinutes)})
요금 정책     : 기본 1시간 ${baseFee.toLocaleString()}원 + 초과 시 시간당 ${hourlyFee.toLocaleString()}원
총 요금 청구  : ${record.fee.toLocaleString()}원
==============================`;
  };

  return (
    <div className="p-4 max-w-4xl mx-auto bg-white rounded shadow">
      <h1 className="text-2xl font-bold mb-4">🅿️ 주차 요금 계산기</h1>

      <div className="grid grid-cols-2 gap-4 mb-4">
        <input
          className="border p-2"
          placeholder="차량 번호"
          value={carNumber}
          onChange={(e) => setCarNumber(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Tab") {
              e.preventDefault();
              handleSetEntryTime();
              setTimeout(() => document.getElementById("entryTime")?.focus(), 10);
            }
          }}
        />
        <input
          className="border p-2"
          placeholder="차종 (선택)"
          value={carType}
          onChange={(e) => setCarType(e.target.value)}
        />
        <input
          id="entryTime"
          className="border p-2 col-span-2"
          placeholder="입차 시간 (예: 07:30)"
          value={entryTime}
          onChange={(e) => {
            let val = e.target.value.replace(/[^0-9]/g, "");
            if (val.length === 3) val = val[0] + ":" + val.slice(1);
            else if (val.length === 4) val = val.slice(0, 2) + ":" + val.slice(2);
            setEntryTime(val);
          }}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              if (window.confirm("입차 등록하시겠습니까?")) {
                handleAddEntry();
              }
            }
          }}
        />
      </div>

      <h2 className="text-lg font-semibold mt-6 mb-2">📋 입차 차량 목록</h2>
      <table className="w-full border text-sm">
        <thead className="bg-gray-100">
          <tr>
            <th className="border p-1 w-[10%]">차량번호</th>
            <th className="border p-1 w-[10%]">차종</th>
            <th className="border p-1 w-[10ch]">입차 시간</th>
            <th className="border p-1 w-[10ch]">출차 시간</th>
            <th className="border p-1 w-[10%]">요금</th>
            <th className="border p-1 w-[10%]">수정</th>
            <th className="border p-1 w-[40%]">작업</th>
          </tr>
        </thead>
        <tbody>
          {parkingRecords.map((r) => (
            <tr key={r.id} className="text-center">
              <td className="border p-1">
                <input
                  className="w-full"
                  value={r.carNumber}
                  onChange={(e) => handleEditChange(r.id, "carNumber", e.target.value)}
                  disabled={editingId !== r.id}
                />
              </td>
              <td className="border p-1">
                <input
                  className="w-full"
                  value={r.carType}
                  onChange={(e) => handleEditChange(r.id, "carType", e.target.value)}
                  disabled={editingId !== r.id}
                />
              </td>
              <td className="border p-1">
                <input
                  className="w-full max-w-[10ch]"
                  value={r.entryTime}
                  onChange={(e) => handleEditChange(r.id, "entryTime", e.target.value)}
                  disabled={editingId !== r.id}
                />
              </td>
              <td className="border p-1">
                <input
                  className="w-full max-w-[10ch]"
                  value={r.exitTime || ""}
                  onChange={(e) => handleEditChange(r.id, "exitTime", e.target.value)}
                  disabled={editingId !== r.id || !r.exitTime}
                />
              </td>
              <td className="border p-1">{r.fee?.toLocaleString() || "-"}</td>
              <td className="border p-1">
                {editingId === r.id ? (
                  <button className="text-green-600 underline" onClick={() => handleEditDone(r.id)}>
                    완료
                  </button>
                ) : (
                  <button className="text-blue-600 underline" onClick={() => setEditingId(r.id)}>
                    수정
                  </button>
                )}
              </td>
              <td className="border p-1">
                <button
                  className="text-green-600 underline"
                  onClick={() => handleSetExitAndCalculate(r.id)}
                >
                  정산
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {activeReceipt && (
        <div className="mt-6 p-4 bg-gray-100 border rounded text-sm whitespace-pre-wrap">
          <h3 className="font-semibold mb-2">📜 상세 영수증</h3>
          <div ref={printRef}>
            <pre>{generateReceiptText(activeReceipt)}</pre>
          </div>
          <div className="mt-2 flex gap-3">
            <button onClick={() => setActiveReceipt(null)} className="text-blue-600 underline">
              닫기
            </button>
            {activeReceipt.fee && (
              <button onClick={handlePrint} className="text-green-600 underline">
                PDF 저장 / 인쇄
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
